package com.example.demo.staffing;

import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.apache.poi.ss.usermodel.*;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.*;
import java.math.*;
import java.util.*;
import static com.example.demo.accounting.PayrollBreakdown.money;

@Service @RequiredArgsConstructor @Transactional(isolation=org.springframework.transaction.annotation.Isolation.REPEATABLE_READ)
public class StaffingExportService {
    private final StaffingService service;
    private final ObjectMapper json;
    public byte[] payroll(long company,String month,List<Long> selected)throws IOException {
        var rows=service.payrollBasis(company,month,selected);
        try(var workbook=new XSSFWorkbook();var out=new ByteArrayOutputStream()){
            var sheet=workbook.createSheet("Approved staffing time");
            String[] headings={"Time entry","Worker","Classification","Pay basis","Client","Assignment","Work date","Currency","Regular hours","Overtime hours","Pay rate","Overtime pay rate","Hourly pay reference","Payroll contract","Invoice"};header(workbook,sheet,headings);int index=1;
            for(var entry:rows){var row=sheet.createRow(index++);Object[] values={entry.get("id"),entry.get("employee"),entry.get("classification"),entry.get("pay_basis"),entry.get("client"),entry.get("title"),entry.get("work_date"),entry.get("currency"),entry.get("regular_hours"),entry.get("overtime_hours"),entry.get("pay_rate"),entry.get("overtime_pay_rate"),null,entry.get("payroll_contract_id"),entry.get("invoice_id")};for(int n=0;n<values.length;n++)cell(row,n,values[n]);
                if("HOURLY".equals(entry.get("pay_basis")) && !"VENDOR_WORKER".equals(entry.get("classification")))row.createCell(12).setCellFormula("ROUND(I"+index+"*K"+index+"+J"+index+"*L"+index+",2)");
            }
            var notes=workbook.createSheet("Read me");String[] text={"Approved staffing time for "+month+". Pay rates are snapshots captured on the time entry.","Hourly pay reference is a preparation input, not a payslip, net salary, tax calculation or payment.","Salaried and vendor workers have no hourly pay reference. Use payroll contracts or vendor invoices as appropriate.","W-2/independent contractor/vendor classification requires review. Immigration status never determines classification or deductions.","Review overtime, applicable minimum/prevailing wages, work authorization, tax elections and other earnings before preparing payroll.","Use existing Payroll contracts and Manual Payroll to prepare actual payslips. No payroll is generated by this export."};for(int n=0;n<text.length;n++)notes.createRow(n).createCell(0).setCellValue(text[n]);notes.setColumnWidth(0,120*256);finish(sheet);workbook.setForceFormulaRecalculation(true);workbook.write(out);return out.toByteArray();
        }
    }
    public byte[] invoice(long company,long id)throws IOException {
        var invoice=service.invoiceDetail(company,id);
        try(var workbook=new XSSFWorkbook();var out=new ByteArrayOutputStream()){
            var sheet=workbook.createSheet("Client invoice");var client=json.readValue((String)invoice.get("client_snapshot"),Map.class);
            String[] info={"Service invoice STAFF-"+id,"Status: "+invoice.get("status"),"Client: "+client.get("name"),"Billing email: "+Objects.toString(client.get("email"),""),"Billing address: "+Objects.toString(client.get("address"),""),"Invoice date: "+invoice.get("invoice_date")+" · Due: "+invoice.get("due_date"),"Currency: "+invoice.get("currency")};for(int n=0;n<info.length;n++)sheet.createRow(n).createCell(0).setCellValue(info[n]);
            var header=sheet.createRow(8);String[] labels={"Description","Regular hours","Overtime hours","Bill rate","Overtime bill rate","Amount"};for(int n=0;n<labels.length;n++)header.createCell(n).setCellValue(labels[n]);
            @SuppressWarnings("unchecked")var lines=(List<Map<String,Object>>)invoice.get("lines");int index=9;
            for(var line:lines){var row=sheet.createRow(index++);Object[] values={line.get("description"),line.get("regular_hours"),line.get("overtime_hours"),line.get("bill_rate"),line.get("overtime_bill_rate"),line.get("amount")};for(int n=0;n<values.length;n++)cell(row,n,values[n]);}
            for(var pair:List.of(new Object[]{"Subtotal",invoice.get("subtotal")},new Object[]{"Tax % (entered by finance)",invoice.get("tax_percent")},new Object[]{"Tax amount",invoice.get("tax_amount")},new Object[]{"Total",invoice.get("total")})){var row=sheet.createRow(index++);cell(row,4,pair[0]);cell(row,5,pair[1]);}
            sheet.createRow(index+1).createCell(0).setCellValue("Amounts and tax treatment require finance review. This export does not initiate delivery or payment.");finish(sheet);sheet.setColumnWidth(0,65*256);workbook.write(out);return out.toByteArray();
        }
    }
    private void header(Workbook workbook,Sheet sheet,String[] labels){var row=sheet.createRow(0);var style=workbook.createCellStyle();style.setFillForegroundColor(IndexedColors.DARK_BLUE.getIndex());style.setFillPattern(FillPatternType.SOLID_FOREGROUND);var font=workbook.createFont();font.setColor(IndexedColors.WHITE.getIndex());font.setBold(true);style.setFont(font);for(int n=0;n<labels.length;n++){var cell=row.createCell(n);cell.setCellValue(labels[n]);cell.setCellStyle(style);}}
    private void cell(Row row,int col,Object value){if(value==null)return;var cell=row.createCell(col);if(value instanceof Number n)cell.setCellValue(n.doubleValue());else cell.setCellValue(value.toString());}
    private void finish(Sheet sheet){sheet.createFreezePane(0,1);for(int col=0;col<sheet.getRow(0).getLastCellNum();col++)sheet.setColumnWidth(col,24*256);sheet.getPrintSetup().setLandscape(true);sheet.setFitToPage(true);}
}
